        "description": "昨晚打呼噜时长展示文本",
        "sampleValue": "打呼 3分"
      },
      "reminderThresholdText": {
        "type": "string",
        "description": "深睡偏低提醒项展示文本",
        "sampleValue": "就医"
      },
      "reminderTurnText": {
        "type": "string",
        "description": "翻身提醒项数值展示文本",
        "sampleValue": "12次"
      },
      "reminderSnoreText": {
        "type": "string",
        "description": "打呼噜提醒项数值展示文本",
        "sampleValue": "3分"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠图标，适合用于睡眠监督卡片中的深睡状态或睡眠摘要提醒。"
    },
    {
      "src": "resources/base/media/icon_alarm_clock1.png",
      "description": "闹钟图标，适合用于睡眠监督卡片中的提醒项或夜间事件提示。"
    },
    {
      "src": "resources/base/media/icon_remind.png",
      "description": "提醒图标，适合用于睡眠监督卡片中的异常提醒或健康建议。"
    }
  ]
}

